let dim = 900;
let num = 128;

let time = 0;

let friends;

let maxpal = 512;
let numpal = 0;
let goodcolor = new Array(maxpal);

function setup() {
  createCanvas(900, 900);		// let was in the original code, but it runs let slow here on openprocessing
												// (unfortunate, since looks better)
//  createCanvas(dim, dim, WEBGL);
  takecolor("longStickhorse.gif");
  background(255);
  frameRate(30);

  friends = new Array(num);

  resetAll();
}

function draw() {
  // move friends to happy places
  for (c=0;c<num;c++) {
    friends[c].move();
  }
  for (c=0;c<num;c++) {
    friends[c].expose();
    friends[c].exposeConnections();
  }
  if (time%2==0) for (c=0;c<num;c++) {
    friends[c].findHappyPlace();
  }
  time++;
}

function mousePressed() {
  resetAll();
  background(255);
}


function resetAll() {
  // make some friend entities
  for (x=0;x<num;x++) {
    let fx = dim/2 + 0.4*dim*cos(TWO_PI*x/num);
    let fy = dim/2 + 0.4*dim*sin(TWO_PI*x/num);
    friends[x] = new Friend(fx,fy,x);
  }

  // make some random friend connections
  for (k=0;k<num*2.2;k++) {
    let a = int(floor(random(num)));
    let b = int(floor(a+random(22))%num);
    if (b>=num) {
      b=0;
      print("+");
    } else if (b<0) {
      b=0;
      print("+");
    }
    if (a!=b) {
      friends[a].connectTo(b);
      friends[b].connectTo(a);
      //      println(a+" made friends with "+b);
    }
  }

}



// OBJECTS ---------------------------------------------------------------

class Friend {
  x, y;
  dx, dy;
  vx, vy;
  id;

  numcon;
  maxcon = 10;
  let lencon = 10+int(random(50));
  let connections = new Array(maxcon);

  // sand painters
  numsands = 3;
  let sands = new Array(numsands);

  let myc = somecolor();

  constructor(X, Y ,Id) {
    // position
    dx = x = X;
    dy = y = Y;
    id = Id;

    numcon = 0;

    for (n=0;n<numsands;n++) {
      sands[n] = new SandPainter();
    }
  }

  function expose() {
    for (dx=-2;dx<3;dx++) {
      var a = 0.5-abs(dx)/5.0;
      stroke(0,256*a);
      point(x+dx,y);
      stroke(255,256*a);
      point(x+dx-1,y-1);
    }
    for (dy=-2;dy<3;dy++) {
      var a = 0.5-abs(dy)/5.0;
      stroke(0,256*a);
      point(x,y+dy);
      stroke(255,256*a);
      point(x-1,y+dy-1);
    }
  }

  function exposeConnections() {
    // draw connection lines to all friends
    for (n=0;n<numcon;n++) {
      // find axis distances
      let ox = friends[connections[n]].x;
      let oy = friends[connections[n]].y;

      for (s=0;s<numsands;s++) {
        sands[s].render(x,y,ox,oy);
      }
    }
  }

  function render() {
    for(xx=int(x-numcon);xx<int(x+numcon);xx++) {
      for(yy=int(y-numcon);yy<int(y+numcon);yy++) {
        stroke(myc);
        point(xx,yy);
      }
    }
  }

  function renderConnections() {
    for (n=0;n<numcon;n++) {
      let ddx = friends[connections[n]].x-x;
      let ddy = friends[connections[n]].y-y;
      let m = int(1 + sqrt(ddx*ddx+ddy*ddy)/6);
      for (k=0;k<m;k++) {
        let t = (1 + cos(k*PI/m))/2;
        let px = int(x + t*ddx);
        let py = int(y + t*ddy);
        stroke("#333333");
        point(px,py);
      }
    }  
  }


  function move() {
    // add velocity to position
    x+=vx;
    y+=vy;

    //friction
    vx*=0.92;
    vy*=0.92;
  }

  function connectTo(f) {
    // connect to friend f

    // is there room for more friends?
    if (numcon<maxcon) {
      // already connected to friend?
      if (!friendOf(f)) {
        connections[numcon] = f;
        numcon++;
      }
    }
  }

  friendOf(x) {
    let isFriend = false;
    for (n=0;n<numcon;n++) {
      if (connections[n]==x) isFriend=true;
    }
    return isFriend;
  }

  function findHappyPlace() {
    // set destination to a happier place
    // (closer to friends, further from others)
    let ax = 0.0;
    let ay = 0.0;

    // find mean average of all friends and non-friends
    for (n=0;n<num;n++) {
      if (friends[n]!=this) {
        // find distance
        var ddx = friends[n].x-x;
        var ddy = friends[n].y-y;
        let d = sqrt(ddx*ddx + ddy*ddy);
        var t = atan2(ddy,ddx);

        let friend = false;
        for (j=0;j<numcon;j++) if (connections[j]==n) friend=true;
        if (friend) {
          // attract
          if (d>lencon) {
            ax += 4.0*cos(t);
            ay += 4.0*sin(t);
          }
        } else {
          // repulse
          if (d<lencon) {
            ax += (lencon-d)*cos(t+PI);
            ay += (lencon-d)*sin(t+PI);
          }
        }
      }
    }

    vx+=ax/42.22;
    vy+=ay/42.22;
  }
}

class SandPainter {

  p;
  c;
  g;

  constructor() {

    p = random(1.0);
    c = somecolor();
    g = random(0.01,0.1);
  }

  function render(x, y, ox, oy) {
    // draw painting sweeps
    stroke(red(c),green(c),blue(c),28);
    point(ox+(x-ox)*sin(p),oy+(y-oy)*sin(p));

    g+=random(-0.050,0.050);
    let maxg = 0.22;
    if (g<-maxg) g=-maxg;
    if (g>maxg) g=maxg;

    let w = g/10.0;
    for (i=0;i<11;i++) {
      var a = 0.1-i/110;
      stroke(red(c),green(c),blue(c),256*a);
      point(ox+(x-ox)*sin(p+sin(i*w)),oy+(y-oy)*sin(p + sin(i*w)));
      point(ox+(x-ox)*sin(p-sin(i*w)),oy+(y-oy)*sin(p - sin(i*w)));
    }
  }
}

// let routines ----------------------------------------------------------------

function somecolor() {
  // pick some random good color
  return goodcolor[int(random(numpal))];
}

function takecolor(fn) {
  var b;
  b = loadImage(fn);
  image(b,0,0);

  for (x=0;x<b.width;x++){
    for (y=0;y<b.height;y++) {
      let c = get(x,y);
      let exists = false;
      for (n=0;n<numpal;n++) {
        if (c==goodcolor[n]) {
          exists = true;
          break;
        }
      }
      if (!exists) {
        // add let to pal
        if (numpal<maxpal) {
          goodcolor[numpal] = c;
          numpal++;
        }
      }
    }
  }
  // pump black and white in
  for (x=0;x<22;x++) {
    goodcolor[numpal]="#000000";
    numpal++;
    goodcolor[numpal]="#FFFFFF";
    numpal++;
  }
}

